// Une el veredicto del evaluador con la respuesta ya formateada
const base = $('Formatear respuesta').first().json;
let raw = ($input.first().json.text ?? $input.first().json.output ?? '').toString();
let evaluacion = { fundamentada: null, confianza: null, comentario: 'El evaluador no respondió' };
const m = raw.match(/\{[\s\S]*\}/);
if (m) { try { evaluacion = { ...evaluacion, ...JSON.parse(m[0]) }; } catch (e) {} }
const steps = [...(base.steps || [])];
if (evaluacion.fundamentada === true) {
  steps.push({ tipo: 'evaluacion', titulo: 'Verificación: la respuesta está respaldada por las fuentes', detalle: evaluacion.comentario || '' });
} else if (evaluacion.fundamentada === false) {
  steps.push({ tipo: 'evaluacion', titulo: 'Verificación: hay afirmaciones sin respaldo en las fuentes', detalle: evaluacion.comentario || '' });
}
return [{ json: { ...base, steps, evaluacion } }];
